function renderFinanceControl(c){head('Finance Control','Source-driven Money In and Money Out shown side by side. No duplicate manual ledger posting.');const moneyIn=data.center_payments||[],moneyOut=data.vendor_payments||[],receivable=data.center_receivables||[],payable=data.vendor_payables||[],received=sumField(moneyIn,'amount_paise'),paid=sumField(moneyOut,'amount_paise'),centerDue=sumField(receivable,'outstanding_paise'),vendorDue=sumField(payable,'outstanding_paise'),balance=received-paid;c.innerHTML=`<section class="stats"><article><span class="money-in-label">↓ Money In</span><strong class="balance-positive">${money(received)}</strong></article><article><span class="money-out-label">↑ Money Out</span><strong class="balance-negative">${money(paid)}</strong></article><article><span>Net Cash Balance</span><strong class="${balance<0?'balance-negative':'balance-positive'}">${money(balance)}</strong></article><article><span>Center Due / Vendor Due</span><strong>${money(centerDue)} / ${money(vendorDue)}</strong></article></section><section class="recon-grid"><article class="recon-column"><h2 class="money-in-label"><span class="money-arrow">↓</span>Money In · From Centers</h2>${moneyIn.map(p=>{const r=receivable.find(x=>x.id===p.receivable_id);return`<div class="recon-row"><div><b>${esc(r?.school_name||p.school_name||'Center receipt')}</b><small>${esc(p.payment_date||'')} · ${esc(p.payment_mode||'')} · ${esc(p.reference||'')}</small></div><strong class="balance-positive">↓ ${money(p.amount_paise)}</strong></div>`}).join('')||'<p class="empty">No center payments received yet.</p>'}</article><article class="recon-column"><h2 class="money-out-label"><span class="money-arrow">↑</span>Money Out · To Vendors</h2>${moneyOut.map(p=>{const r=payable.find(x=>x.id===p.payable_id);return`<div class="recon-row"><div><b>${esc(r?.vendor_name||p.vendor_name||'Vendor payment')}</b><small>${esc(p.payment_date||'')} · ${esc(p.payment_mode||'')} · ${esc(p.reference||'')}</small></div><strong class="balance-negative">↑ ${money(p.amount_paise)}</strong></div>`}).join('')||'<p class="empty">No vendor payments posted yet.</p>'}</article></section><section class="panel"><h2>Outstanding Balance</h2><div class="recon-grid"><div class="recon-row"><div><b>Centers yet to pay</b><small>Generated from approved center orders</small></div><strong>${money(centerDue)}</strong></div><div class="recon-row"><div><b>Vendors yet to be paid</b><small>Generated from accepted warehouse receipts</small></div><strong>${money(vendorDue)}</strong></div></div></section>`}
render=function(){if(!data.center_orders)return;const c=$('#content');if(tab==='order_control'){renderOrderControl(c);return}if(tab==='demand'){renderDemandPlanning(c);return}if(tab==='warehouse'){renderBulkWarehouse(c);return}if(tab==='packing'){renderPackingControl(c);return}if(tab==='finance_control'){renderFinanceControl(c);return}if(tab==='money_in'){tab='center_finance';legacySupplyRender();tab='money_in';return}if(tab==='money_out'){tab='finance';legacySupplyRender();tab='money_out';return}if(tab==='vendors'){renderVendorMaster(c);return}if(tab==='materials'){renderMaterialHub(c);return}if(tab==='kits'){renderKitBuilder(c);return}if(tab==='vendor_pos'){renderVendorPurchaseOrdersV4(c);return}legacySupplyRender()};
if(token){renderSupplyNav();render()}
